    { title: "Version history",
      body: "Down here on the right is your version history — ELI automatically saves past versions of your document as you run certain tools. Try it: click the camera to take a snapshot now, then open the history to view it. You can restore any earlier version anytime. And if someone tries to sneak in a redline without tracking it, ELI will know.",
      target: function () { return _q("._eli3_footer_slot_right") || _q("._eli3_status_bar"); } },
    { title: "Zoom",
      body: "Make the panel bigger or smaller to fit your screen — especially handy on a laptop.",
