          (_idx > 0 ? '<button type="button" class="_eli3_tour_back _eli3_tour_back_intro">Back</button>' : '') +
          '<button type="button" class="_eli3_tour_next _eli3_tour_next_intro">' + _esc(step.cta || "Start the tour →") + '</button>' +
        '</div>';
    } else {
      card.classList.remove("_intro");
      card.innerHTML =
        '<div class="_eli3_tour_accent"></div>' +
        '<div class="_eli3_tour_hd">' +
          '<div class="_eli3_tour_av">' + _mascot() + '</div>' +
