jsonTools.css:
/* dashboard_tour — premium guided tour overlay. Navy/gold to match the
   ELI dashboard chrome. Sized for laptops (compact card). */

/* z below kernel dialogs (9999+) so the Help/Contact, Settings, and Customize
   dialogs the tour invites you to open render ABOVE the spotlight. Still well
   above dashboard chrome. */
#_eli3_tour_root { position: fixed; inset: 0; z-index: 9500; pointer-events: none; }

/* Single spotlight: a transparent box over the target. Its enormous
   box-shadow dims the whole screen (no width math → immune to laptop zoom);
   the gold border is the ring. pointer-events:none so the Home button and the
   rest of the chrome stay clickable. */
._eli3_tour_spot {
  position: fixed; pointer-events: none; border-radius: 12px;
  border: 2px solid #c9a227;
  box-shadow: 0 0 0 9999px rgba(13, 27, 42, 0.62),
              0 0 0 3px rgba(201, 162, 39, 0.22), 0 0 22px 4px rgba(201, 162, 39, 0.45);
  z-index: 100002;
  transition: left 0.28s cubic-bezier(0.4, 0, 0.2, 1), top 0.28s cubic-bezier(0.4, 0, 0.2, 1),
              width 0.28s cubic-bezier(0.4, 0, 0.2, 1), height 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  animation: _eli3_tour_pulse 2s ease-in-out infinite;
}
/* Intro splash — full backdrop, no visible ring (0-size box, shadow only). */
._eli3_tour_spot._nohole { border-color: transparent; animation: none; }
@keyframes _eli3_tour_pulse {
  0%, 100% { box-shadow: 0 0 0 9999px rgba(13,27,42,0.62), 0 0 0 3px rgba(201,162,39,0.20), 0 0 18px 3px rgba(201,162,39,0.38); }
  50%      { box-shadow: 0 0 0 9999px rgba(13,27,42,0.62), 0 0 0 4px rgba(201,162,39,0.30), 0 0 26px 6px rgba(201,162,39,0.55); }
}

/* The mascot speech card */
._eli3_tour_card {
  position: fixed; z-index: 100010; pointer-events: auto;
  width: min(300px, 88vw); box-sizing: border-box;
  background: linear-gradient(160deg, #0d1b2a 0%, #1b263b 100%);
  border: 1px solid rgba(201, 162, 39, 0.55); border-radius: 14px;
  box-shadow: 0 18px 50px rgba(13, 27, 42, 0.55), 0 2px 0 rgba(255, 255, 255, 0.04) inset;
  color: #e2e8f0; overflow: hidden;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  transition: left 0.28s cubic-bezier(0.4, 0, 0.2, 1), top 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}
._eli3_tour_card._in { animation: _eli3_tour_cardin 0.26s cubic-bezier(0.34, 1.4, 0.5, 1); }
._eli3_tour_card._out { opacity: 0; transform: scale(0.97); transition: opacity 0.16s ease, transform 0.16s ease; }
@keyframes _eli3_tour_cardin {
  0% { opacity: 0; transform: translateY(6px) scale(0.98); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

._eli3_tour_accent {
  height: 3px; width: 100%;
  background: linear-gradient(90deg, #b8901f 0%, #f2d866 50%, #b8901f 100%);
}

/* ── Intro splash — giant ELI welcome ───────────────────────────────── */
._eli3_tour_card._intro {
  width: min(440px, 92vw); text-align: center; padding-bottom: 22px;
}
._eli3_tour_x_intro {
  position: absolute; top: 8px; right: 10px;
  border: none; background: transparent; color: #94a3b8;
  font-size: 15px; line-height: 1; cursor: pointer; padding: 2px 5px; border-radius: 5px;
}
._eli3_tour_x_intro:hover { color: #e2e8f0; background: rgba(255, 255, 255, 0.08); }
._eli3_tour_introav {
  width: 104px; height: 104px; margin: 22px auto 6px; border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #16263c, #0b1626);
  border: 2px solid #c9a227; box-shadow: 0 0 26px rgba(201, 162, 39, 0.45);
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
._eli3_tour_introav svg, ._eli3_tour_introav img { width: 86%; height: 86%; display: block; }
._eli3_tour_introtitle {
  font: 800 22px/1.2 Georgia, 'Book Antiqua', serif; color: #f2d866;
  margin: 6px 22px 0;
}
._eli3_tour_introtxt {
  font: 400 14px/1.6 Inter, sans-serif; color: #cbd5e1; margin: 12px 26px 20px;
  max-height: 44vh; overflow: auto;
}
._eli3_tour_introbtns { display: flex; justify-content: center; align-items: center; gap: 10px; }
._eli3_tour_back_intro { padding: 11px 18px; font-size: 12px; }
._eli3_tour_next_intro {
  border: 1px solid #b8901f; color: #3a2c05; font: 800 13px/1 Inter, sans-serif;
  padding: 11px 26px; border-radius: 9px; cursor: pointer;
  background: linear-gradient(135deg, #f2d866 0%, #c9a227 60%, #b8901f 100%);
  box-shadow: 0 3px 12px rgba(201, 162, 39, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  transition: filter 0.12s ease, transform 0.12s ease;
}
._eli3_tour_next_intro:hover { filter: brightness(1.06); transform: translateY(-1px); }
._eli3_tour_next_intro:active { transform: translateY(0); }

._eli3_tour_hd {
  display: flex; align-items: center; gap: 10px; padding: 11px 12px 9px; cursor: move;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07); user-select: none;
}
._eli3_tour_av {
  flex: 0 0 auto; width: 40px; height: 40px; border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #16263c, #0b1626);
  border: 1.5px solid #c9a227; box-shadow: 0 0 14px rgba(201, 162, 39, 0.35);
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
._eli3_tour_av svg, ._eli3_tour_av img { width: 88%; height: 88%; display: block; }
._eli3_tour_idwrap { display: flex; flex-direction: column; gap: 1px; flex: 1 1 auto; min-width: 0; }
._eli3_tour_name { font: 800 13px/1 Georgia, 'Book Antiqua', serif; letter-spacing: 0.04em; color: #f2d866; }
._eli3_tour_sub { font: 600 8.5px/1 Inter, sans-serif; letter-spacing: 0.16em; text-transform: uppercase; color: #7c8aa0; }
._eli3_tour_minbtn {
  flex: 0 0 auto; border: 1px solid rgba(201, 162, 39, 0.45);
  background: rgba(201, 162, 39, 0.12); color: #f2d866;
  font: 800 10px/1 Inter, sans-serif; letter-spacing: 0.03em; cursor: pointer;
  padding: 4px 7px; border-radius: 6px;
}
._eli3_tour_minbtn:hover { color: #fff; background: rgba(201, 162, 39, 0.24); }
._eli3_tour_x {
  flex: 0 0 auto; border: none; background: transparent; color: #94a3b8;
  font-size: 14px; line-height: 1; cursor: pointer; padding: 2px 4px; border-radius: 5px;
}
._eli3_tour_x:hover { color: #e2e8f0; background: rgba(255, 255, 255, 0.08); }

/* Collapsed state — shown while the user is exploring a clicked element
   (e.g. Settings). Only the header + Back/Next remain so the panel is clear. */
._eli3_tour_card._min ._eli3_tour_body { display: none; }
._eli3_tour_card._min ._eli3_tour_hd { border-bottom: none; }

._eli3_tour_body { padding: 11px 14px 4px; }
._eli3_tour_title { font: 700 14px/1.25 Georgia, 'Book Antiqua', serif; color: #fff; margin-bottom: 5px; }
._eli3_tour_txt { font: 400 12.5px/1.55 Inter, sans-serif; color: #cbd5e1; }

._eli3_tour_ft {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 10px 14px 13px;
}
/* Many stops now — let the dots stay compact and wrap rather than push the
   Back/Next buttons off the card edge. */
._eli3_tour_dots { display: flex; align-items: center; flex-wrap: wrap; gap: 3px; flex: 1 1 auto; min-width: 0; }
._eli3_tour_dot {
  width: 5px; height: 5px; border-radius: 50%; background: rgba(255, 255, 255, 0.20);
  transition: background 0.2s ease, transform 0.2s ease;
}
._eli3_tour_dot._on { background: #c9a227; transform: scale(1.25); box-shadow: 0 0 8px rgba(201, 162, 39, 0.6); }
._eli3_tour_btns { display: flex; align-items: center; gap: 7px; flex: 0 0 auto; }

._eli3_tour_back {
  border: 1px solid rgba(255, 255, 255, 0.18); background: rgba(255, 255, 255, 0.06);
  color: #cbd5e1; font: 700 11px/1 Inter, sans-serif; padding: 7px 11px; border-radius: 7px;
  cursor: pointer; transition: background 0.12s ease;
}
._eli3_tour_back:hover { background: rgba(255, 255, 255, 0.13); }
._eli3_tour_next {
  border: 1px solid #b8901f; color: #3a2c05; font: 800 11px/1 Inter, sans-serif;
  padding: 7px 14px; border-radius: 7px; cursor: pointer;
  background: linear-gradient(135deg, #f2d866 0%, #c9a227 60%, #b8901f 100%);
  box-shadow: 0 2px 8px rgba(201, 162, 39, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  transition: filter 0.12s ease, transform 0.12s ease;
}
._eli3_tour_next:hover { filter: brightness(1.06); transform: translateY(-1px); }
._eli3_tour_next:active { transform: translateY(0); }
